#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
cd "$REPO_ROOT"

OCI_DIR="${HOME}/.oci"
ENV_FILE="${OCI_DIR}/wattloft.env"
AGENT_NOTE="${OCI_DIR}/wattloft-agent.txt"
mkdir -p "$OCI_DIR"

TOTAL_STAGES=5

banner "Wattloft deSEC: one hostname for Plant view and Server B"

# ── 1. Choose the name ───────────────────────────────────────────────────
stage "Choose the hostname"
say "Issue #7 / ADR 0023: one deSEC DNS name. Plant view is https:// that name;"
say "Loggers dial the same name on the ingest TCP port (not 443)."
say "A free name under dedyn.io needs no registrar. Do not put Cloudflare (or any"
say "CDN proxy) in front: it would swallow Server B's raw TCP."
note "Suggested: wattloft.dedyn.io  — if taken, try wattloft-plant, ulder-wattloft, …"
ask WATTLOFT_HOSTNAME "Hostname (wattloft or wattloft.dedyn.io):"
WATTLOFT_HOSTNAME=$(printf '%s' "$WATTLOFT_HOSTNAME" | tr '[:upper:]' '[:lower:]' | tr -d '[:space:]')
if [[ "$WATTLOFT_HOSTNAME" != *.dedyn.io ]]; then
  WATTLOFT_HOSTNAME="${WATTLOFT_HOSTNAME}.dedyn.io"
fi
if [[ ! "$WATTLOFT_HOSTNAME" =~ ^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.dedyn\.io$ ]]; then
  warn "Need a lowercase label then .dedyn.io (letters, digits, hyphens)."
  exit 1
fi
note "will register: $WATTLOFT_HOSTNAME"
write_env WATTLOFT_HOSTNAME "$WATTLOFT_HOSTNAME"

# ── 2. Account + domain ──────────────────────────────────────────────────
stage "Create the deSEC account and domain"
say "deSEC is free. The first domain can be created on the signup form."
say "If $WATTLOFT_HOSTNAME is taken, pick another label and re-run from stage 1."
open_url "https://desec.io/signup"
step "If you already have a deSEC account: Log In instead, then skip to the note below."
step "Email: an inbox you can open in the next minute (activation link expires in 12 hours)."
step "Password: yours; the later agent never needs it. Do not reuse a GitHub/OCI password."
step "Choose: Register a new domain under dedyn.io (dynDNS)."
step "Domain name: ${WATTLOFT_HOSTNAME}"
step "Solve the CAPTCHA, accept Terms of Use and Privacy Policy, Sign up."
step "Open the confirmation email and click the link."
note "Already had an account? After login, click the domain list + and create ${WATTLOFT_HOSTNAME}."
pause "Press Enter after the domain exists on the account."
if ! confirm "Is ${WATTLOFT_HOSTNAME} listed in the deSEC domain list?"; then
  warn "If the name was taken, choose another label and re-run this wizard."
  exit 1
fi

# ── 3. Long-lived API token ──────────────────────────────────────────────
stage "Create a long-lived API token"
say "The later agent uses this token to point an A record at the reserved public IPv4"
say "once the VM exists. Login sessions expire; this token must not."
say "The token secret is shown once (a popup). The Token ID in the table is not the secret."
open_url "https://desec.io/tokens"
step "If you are not logged in, log in, then open Token Management again."
step "Click + to create a token."
step "Name: wattloft-oci"
step "Leave Advanced settings alone: no expiry, no IP restriction."
step "Do not enable Create domains or Delete domains. Record updates on an existing domain do not need those."
step "Create, then immediately copy the token secret from the popup (long random string)."
step "If the popup is gone, delete this token row and create another — the ID column is useless to us."
pause "Press Enter when the secret is on the clipboard."
ask_secret DESEC_TOKEN "Paste the token secret:"
if [[ -z "$DESEC_TOKEN" || ${#DESEC_TOKEN} -lt 16 ]]; then
  warn "That does not look like a deSEC token secret."
  exit 1
fi
write_env DESEC_TOKEN "$DESEC_TOKEN"

# ── 4. No A/AAAA yet ─────────────────────────────────────────────────────
stage "Leave the A record empty"
say "Signup or dynDNS may have published your current home IP. That is wrong for Wattloft."
say "The A record must wait for the OCI reserved public IPv4 (ADR 0023). The later agent"
say "writes it with this token. Do not configure a router/ddclient updater for this name."
open_url "https://desec.io/"
step "Log In if needed, then click ${WATTLOFT_HOSTNAME} in the domain list."
step "You should see NS / DNSSEC rows. Those stay."
step "If there is an A or AAAA row (often your home IP), delete it. Trash / delete on that row."
step "Do not add an A record yourself. Do not put this name behind Cloudflare or any CDN proxy."
pause "Press Enter after A and AAAA are gone (or were never there)."
if ! confirm "Are there no A or AAAA records on ${WATTLOFT_HOSTNAME}?"; then
  warn "A leftover home-IP record would send Loggers and Let's Encrypt to the wrong place."
  exit 1
fi

# ── 5. GitHub + agent note ───────────────────────────────────────────────
stage "Hand the name to the issue #7 agent"
say "Hostname is a GitHub variable (public). Token is a GitHub secret."
say "The later agent reads these; Caddy/ACME wait until that agent attaches the reserved IPv4."
set_var WATTLOFT_HOSTNAME "$WATTLOFT_HOSTNAME"
set_secret DESEC_TOKEN "$DESEC_TOKEN"

if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  if confirm "Comment the hostname (not the token) on GitHub issue #7?"; then
    if gh issue comment 7 --body "$(cat <<EOF
deSEC hostname for Plant view and Server B: \`${WATTLOFT_HOSTNAME}\`

A/AAAA are empty until the reserved public IPv4 exists. GitHub variable \`WATTLOFT_HOSTNAME\`; secret \`DESEC_TOKEN\` (API token to publish the A record). DNS-only — no CDN proxy.
EOF
)"; then
      note "commented on issue #7"
    else
      SKIPPED+=("GitHub issue #7 comment")
      warn "could not comment on issue #7"
    fi
  fi
fi

{
  printf '\n'
  printf 'deSEC hostname (ADR 0023 / issue #7): %s\n' "$WATTLOFT_HOSTNAME"
  printf 'GitHub variable WATTLOFT_HOSTNAME; secret DESEC_TOKEN.\n'
  printf 'A record: do not set until the reserved public IPv4 is attached to the VM VNIC.\n'
  printf 'Then PUT an A RRset at the apex (empty subname) via the deSEC API. No CDN proxy.\n'
  printf 'Do not run dynDNS (router/ddclient) against this name — it would overwrite the reserved IP.\n'
} >> "$AGENT_NOTE"
note "appended ${AGENT_NOTE}"

# ──────────────────────────────────────────────────────────────────────────

finish
note "Plant view will be https://${WATTLOFT_HOSTNAME} after the other agent attaches the IP and Caddy gets a cert."
note "Token stays in ${ENV_FILE} — never commit it."
printf '\n'
